        if (System.IO.File.Exists(logoPath))
            return ResolveUrl("~/scratch/logo.png") + "?v=" + System.IO.File.GetLastWriteTime(logoPath).Ticks;
        return "../scratch/logo.png"; // 默认路径
    }

